  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json");
  process.env.FAKE_ARGV_FILE = argvFile;

  await claudeAdapter().run("ping", cwd);
  let argv = readFileSync(argvFile, "utf8").split("\n");
