  await claudeAdapter("sonnet", { maxBudgetUsd: 10 }).run("ping", cwd);
  argv = readFileSync(argvFile, "utf8").split("\n");
  assert.equal(argv[argv.indexOf("--max-budget-usd") + 1], "10");
