  model?: string;        // omit = the adapter's default (codex: the account default)
  bin?: string;          // override the binary path (e.g. a shadowed codex install)
  maxBudgetUsd?: number; // claude only
  effort?: string;       // reasoning effort, to dose token spend. claude: --effort
                         // (low|medium|high|xhigh|max); codex: model_reasoning_effort
                         // (minimal|low|medium|high). NOT supported by agy (effort is
                         // baked into the model name, e.g. "Gemini 3.5 Flash (High)").
                         // Free-form string: the CLI validates it (errors surface in
                         // the raw capture / --doctor), so this parser stays version-agnostic.
};

export type DebateConfig = {
  rounds?: number;
  repo?: string;
  timeoutMinutes?: number;
  participants?: ParticipantSpec[];
  judge?: ParticipantSpec; // the respondeo agent: renders the consolidatio (opt-in)
};

// The inverse of parseDebateConfig: emit the same minimal YAML subset this module
// parses, so a generated config round-trips back through parseDebateConfig unchanged.
// Used by `disputatio --init` to write ~/.config/disputatio/config.yaml. Keep it in
// lock-step with the parser — if one grows a key, so must the other (round-trip test).
const PARTICIPANT_ORDER: (keyof ParticipantSpec)[] = ["adapter", "model", "bin", "maxBudgetUsd", "effort"];

// Quote a scalar only when leaving it bare would change how the parser reads it — namely
// edge whitespace or an empty value (both eaten by the parser otherwise). Plain values
// like model names with spaces/parens ("Gemini 3.5 Flash (High)") stay unquoted; the
// parser reads the whole rest-of-line. A value with a `(^|\s)#` is UNREPRESENTABLE — the
// parser strips trailing comments before handling quotes, so quoting can't save it; we
// refuse it loudly rather than write config that silently round-trips to something else.
function emitScalar(v: string | number): string {
  if (typeof v === "number") return String(v);
  if (/(^|\s)#/.test(v)) throw new Error(`config value cannot contain a "#" comment marker: ${JSON.stringify(v)}`);
  return v === "" || v !== v.trim() ? JSON.stringify(v) : v;
}

function emitSpec(spec: ParticipantSpec, indent: string, firstPrefix: string): string {
  const lines: string[] = [];
  let prefix = firstPrefix;
  for (const key of PARTICIPANT_ORDER) {
    const val = spec[key];
    if (val === undefined) continue;
    lines.push(`${prefix}${key}: ${emitScalar(val)}`);
    prefix = indent; // only the first key carries the "- " list marker
  }
  return lines.join("\n");
}

export function serializeDebateConfig(cfg: DebateConfig): string {
  const out: string[] = [];
  if (cfg.rounds !== undefined) out.push(`rounds: ${cfg.rounds}`);
  if (cfg.timeoutMinutes !== undefined) out.push(`timeoutMinutes: ${cfg.timeoutMinutes}`);
  if (cfg.repo !== undefined) out.push(`repo: ${emitScalar(cfg.repo)}`);
  if (cfg.participants) {
    out.push("participants:");
    for (const p of cfg.participants) out.push(emitSpec(p, "    ", "  - "));
  }
  if (cfg.judge) {
    out.push("judge:");
    out.push(emitSpec(cfg.judge, "  ", "  "));
  }
  return out.join("\n") + "\n";
}

const ADAPTERS = new Set<string>(["claude", "agy", "codex", "pi", "copilot-cli"]);
const TOP_KEYS = new Set<string>(["rounds", "repo", "timeoutMinutes", "participants", "judge"]);
const PARTICIPANT_KEYS = new Set<string>(["adapter", "model", "bin", "maxBudgetUsd", "effort"]);
const NUMERIC_KEYS = new Set<string>(["rounds", "timeoutMinutes", "maxBudgetUsd"]);

function fail(lineNo: number, msg: string): never {
  throw new Error(`debate config line ${lineNo}: ${msg}`);
}

function scalar(raw: string, key: string, lineNo: number): string | number {
  let v = raw.trim();
  const quoted = (v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"));
  if (quoted) v = v.slice(1, -1);
  if (v === "") fail(lineNo, `key "${key}" has no value`);
  if (NUMERIC_KEYS.has(key)) {
    const n = Number(v);
    if (!Number.isFinite(n)) fail(lineNo, `key "${key}" must be a number, got "${v}"`);
    return n;
  }
  return v;
}

export function parseDebateConfig(text: string): DebateConfig {
  return parseConfig(text, false);
}

// Bundle children may update only part of an inherited lineup. All other YAML
// validation remains identical; the bundle loader validates the merged lineup.
export function parseDebateConfigOverlay(text: string): DebateConfig {
  return parseConfig(text, true);
}

function parseConfig(text: string, partial: boolean): DebateConfig {
  const cfg: DebateConfig = {};
  let participants: Record<string, string | number>[] | null = null;
  // The judge is a single spec (not a list). The `in*` flags track which block's
  // continuation lines we are currently reading; any new top-level key closes both
  // (so the accumulators are NOT discarded — a later `judge:` must not drop the
  // already-parsed participants, nor a later top key the judge).
  let judge: Record<string, string | number> | null = null;
  let inParticipants = false;
  let inJudge = false;

  const lines = text.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1;
    const noComment = lines[i].replace(/(^|\s)#.*$/, ""); // strip full-line & trailing comments
    if (noComment.trim() === "") continue;

    const top = noComment.match(/^([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);          // key: value (indent 0)
    const item = noComment.match(/^\s+-\s+([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);  //   - key: value
    const cont = noComment.match(/^\s+([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);      //     key: value

    if (top) {
      const [, key, rest] = top;
      if (!TOP_KEYS.has(key)) fail(lineNo, `unknown key "${key}" (known: ${[...TOP_KEYS].join(", ")})`);
      // A new top-level key always ends the current block (but keeps its accumulator).
      inParticipants = key === "participants";
    ...[
      {}, { version: 2, profiles: {} }, { version: "1", profiles: {} },
      { version: 1 }, { version: 1, profiles: null },
      { version: 1, profiles: [] }, { version: 1, profiles: "fast" },
      { version: 1, profiles: 1 }, { version: 1, profiles: true },
    ].map(value => JSON.stringify(value)),
  ];
  for (const text of invalid) {
    await writeFile(bundlePath, text);
    await assert.rejects(loadProfileBundle(bundlePath, "fast"), { code: "INVALID_BUNDLE" });
    assert.equal(await readFile(bundlePath, "utf8"), text);
  }
});

test("rejects malformed selected profiles", async (t) => {
  const { bundlePath } = await fixture(t);
  for (const profile of [null, [], "configs/fast.yaml", 1, true, {}, { config: null }, { config: [] }, { config: 1 }, { config: "" }, { config: "  " }]) {
    const text = JSON.stringify({ version: 1, profiles: { fast: profile } });
    await writeFile(bundlePath, text);
    await assert.rejects(loadProfileBundle(bundlePath, "fast"), { code: "INVALID_BUNDLE" });
    assert.equal(await readFile(bundlePath, "utf8"), text);
  }
});

test("preserves filesystem errors for missing config and bundle files", async (t) => {
  const { bundlePath, configPath, dir } = await fixture(t);
  await rm(configPath);
  await assert.rejects(loadProfileBundle(bundlePath, "fast"), { code: "ENOENT" });
  await assert.rejects(loadProfileBundle(join(dir, "missing.json"), "fast"), { code: "ENOENT" });
});

test("preserves YAML parser errors without modifying the inputs", async (t) => {
  const { bundlePath, configPath } = await fixture(t);
  const invalidYaml = "round: 2\n";
  await writeFile(configPath, invalidYaml);
  const before = await readFile(bundlePath);
  await assert.rejects(loadProfileBundle(bundlePath, "fast"), /debate config line 1: unknown key "round"/);
  assert.equal(await readFile(configPath, "utf8"), invalidYaml);
  assert.deepEqual(await readFile(bundlePath), before);
});

test("inherits through multiple parents, replacing scalars and whole judge and participant specs", async (t) => {
  const { bundlePath, configPath, dir } = await fixture(t);
  const base = "rounds: 3\nrepo: ../repo\ntimeoutMinutes: 10\nparticipants:\n  - adapter: claude\n    model: sonnet\n    effort: high\n  - adapter: codex\n    model: original\njudge:\n  adapter: claude\n  model: opus\n  effort: high\n";
  const childPath = join(dir, "configs", "child.yaml");
  const grandchildPath = join(dir, "grandchild.yaml");
  await writeFile(configPath, base);
  await writeFile(childPath, "rounds: 0\nparticipants:\n  - adapter: claude\n    model: updated\njudge:\n  adapter: codex\n");
  await writeFile(grandchildPath, "repo: ./child-repo\nparticipants:\n  - adapter: pi\n  - adapter: codex\n    effort: low\n  - adapter: agy\n");
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: {
    base: { config: "configs/fast.yaml" },
    child: { extends: "base", config: "configs/child.yaml" },
    grandchild: { extends: "child", config: "grandchild.yaml" },
    alias: { extends: "grandchild" },
  } }));
  const paths = [bundlePath, configPath, childPath, grandchildPath];
  const before = await Promise.all(paths.map(path => readFile(path)));
  const expected = {
    rounds: 0, repo: "./child-repo", timeoutMinutes: 10,
    participants: [
      { adapter: "claude", model: "updated" },
      { adapter: "codex", effort: "low" },
      { adapter: "pi" },
      { adapter: "agy" },
    ],
    judge: { adapter: "codex" },
  };
  const result = await loadProfileBundle(bundlePath, "alias");
  assert.deepEqual(result, expected);
  result.rounds = 99;
  result.participants![0].model = "mutated";
  result.participants![1].effort = "mutated";
  result.participants!.pop();
  result.judge!.model = "mutated";
  assert.deepEqual(await loadProfileBundle(bundlePath, "alias"), expected);
  assert.deepEqual(await loadProfileBundle(bundlePath, "base"), parseDebateConfig(base));
  assert.deepEqual(await Promise.all(paths.map(path => readFile(path))), before);
});

test("omitted child values inherit, and an extends-only profile owns its result", async (t) => {
  const { bundlePath, dir } = await fixture(t);
  await writeFile(join(dir, "scalar.yaml"), "timeoutMinutes: 2\n");
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: {
    base: { config: "configs/fast.yaml" },
    child: { extends: "base", config: "scalar.yaml" },
    alias: { extends: "child" },
  } }));
  const [first, second] = await Promise.all([
    loadProfileBundle(bundlePath, "alias"), loadProfileBundle(bundlePath, "alias"),
  ]);
  assert.deepEqual(first, { ...parseDebateConfig(yaml), timeoutMinutes: 2 });
  first.participants![0].model = "mutated";
  first.judge!.model = "mutated";
  assert.deepEqual(second, { ...parseDebateConfig(yaml), timeoutMinutes: 2 });
});

test("rejects malformed inheritance fields even when config or a parent is valid", async (t) => {
  const { bundlePath } = await fixture(t);
  const invalid = [null, [], {}, 1, true, "", "  "];
  for (const profile of [
    ...invalid.map(value => ({ config: "configs/fast.yaml", extends: value })),
    ...invalid.map(value => ({ config: value, extends: "base" })),
  ]) {
    await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: {
      base: { config: "configs/fast.yaml" }, child: profile,
    } }));
    await assert.rejects(loadProfileBundle(bundlePath, "child"), { code: "INVALID_BUNDLE" });
  }
});

test("rejects cycles and unknown or malformed parents without changing the bundle", async (t) => {
  const { bundlePath } = await fixture(t);
  for (const [profiles, code] of [
    [{ child: { extends: "child" } }, "INVALID_BUNDLE"],
    [{ child: { extends: "parent" }, parent: { extends: "child" } }, "INVALID_BUNDLE"],
    [{ child: { extends: "missing" } }, "UNKNOWN_PROFILE"],
    [{ child: { extends: "constructor" } }, "UNKNOWN_PROFILE"],
    [{ child: { extends: "parent" }, parent: {} }, "INVALID_BUNDLE"],
  ] as const) {
    const text = JSON.stringify({ version: 1, profiles });
    await writeFile(bundlePath, text);
    await assert.rejects(loadProfileBundle(bundlePath, "child"), { code });
    assert.equal(await readFile(bundlePath, "utf8"), text);
  }
});

test("validates the final merged lineup while allowing partial intermediate overlays", async (t) => {
  const { bundlePath, dir } = await fixture(t);
  await writeFile(join(dir, "base.yaml"), "rounds: 1\n");
  await writeFile(join(dir, "one.yaml"), "participants:\n  - adapter: claude\n");
  await writeFile(join(dir, "two.yaml"), "participants:\n  - adapter: codex\n");
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: {
    base: { config: "base.yaml" },
    one: { extends: "base", config: "one.yaml" },
    two: { extends: "one", config: "two.yaml" },
    standalone: { config: "one.yaml" },
  } }));
  await assert.rejects(loadProfileBundle(bundlePath, "one"), /at least 2 participants/);
  await assert.rejects(loadProfileBundle(bundlePath, "standalone"), /at least 2 participants/);
  assert.deepEqual(await loadProfileBundle(bundlePath, "two"), {
    rounds: 1, participants: [{ adapter: "claude" }, { adapter: "codex" }],
  });
  await writeFile(join(dir, "one.yaml"), "participants:\n  - adapter: unknown\n");
  await assert.rejects(loadProfileBundle(bundlePath, "two"), /each participant needs/);
});
"}

