import { readFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { isDeepStrictEqual } from "node:util";
import { parseDebateConfig, parseDebateConfigOverlay, serializeDebateConfig, type DebateConfig } from "./config.ts";

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function bundleError(code: "INVALID_BUNDLE" | "UNKNOWN_PROFILE", message: string): Error {
  return Object.assign(new Error(message), { code });
}

function validateOverrideSpec(value: unknown): void {
  if (!isObject(value)) throw new Error("participant and judge specs must be objects");
  const stringKeys = ["adapter", "model", "bin", "effort"];
  for (const [key, setting] of Object.entries(value)) {
    if (key === "maxBudgetUsd") {
      if (typeof setting !== "number" || !Number.isFinite(setting)) {
        throw new Error("maxBudgetUsd must be a finite number");
      }
    } else if (!stringKeys.includes(key) || typeof setting !== "string") {
      throw new Error(`unknown or invalid spec setting: ${key}`);
    }
  }
  if (typeof value.adapter !== "string") throw new Error("spec requires an adapter");
}

function parseOverrides(value: unknown): { config: DebateConfig; removeJudge: boolean } {
  try {
    if (!isObject(value)) throw new Error("overrides must be an object");
    for (const [key, setting] of Object.entries(value)) {
      switch (key) {
        case "rounds":
        case "timeoutMinutes":
          if (typeof setting !== "number" || !Number.isFinite(setting)) {
            throw new Error(`${key} must be a finite number`);
          }
          break;
        case "repo":
          if (typeof setting !== "string") throw new Error("repo must be a string");
          break;
        case "participants":
          if (!Array.isArray(setting)) throw new Error("participants must be an array");
          setting.forEach(validateOverrideSpec);
          break;
        case "judge":
          if (setting !== null) validateOverrideSpec(setting);
          break;
        default:
          throw new Error(`unknown override key: ${key}`);
      }
    }
    const config = { ...value };
    const removeJudge = config.judge === null;
    if (removeJudge) delete config.judge;
    const parsed = parseDebateConfigOverlay(serializeDebateConfig(config as DebateConfig));
    // The minimal YAML serializer cannot represent every JSON string. Refuse
    // lossy round trips (quotes, escapes, newlines) instead of changing settings.
    if (!isDeepStrictEqual(parsed, config)) throw new Error("override settings do not round-trip through config YAML");
    return { config: parsed, removeJudge };
  } catch (error) {
    throw bundleError("INVALID_BUNDLE", `invalid overrides: ${error instanceof Error ? error.message : String(error)}`);
  }
}

function overlayConfig(parent: DebateConfig, child: DebateConfig): DebateConfig {
  const merged = { ...parent, ...child };
  if (child.participants !== undefined) {
    const participants = [...(parent.participants ?? [])];
    for (const spec of child.participants) {
      const index = participants.findIndex(p => p.adapter === spec.adapter);
      if (index === -1) participants.push(spec);
      else participants[index] = spec;
    }
    merged.participants = participants;
  }
  return merged;
}

// Read and parse afresh on every load: inputs stay untouched and callers own
// their entire configuration, including participant and judge objects.
export async function loadProfileBundle(bundlePath: string, profileName: string): Promise<DebateConfig> {
  const absoluteBundlePath = resolve(bundlePath);
  const text = await readFile(absoluteBundlePath, "utf8");
  let bundle: unknown;
  try {
    bundle = JSON.parse(text);
  } catch {
    throw bundleError("INVALID_BUNDLE", "profile bundle must contain valid JSON");
  }
  if (!isObject(bundle) || bundle.version !== 1) {
    throw bundleError("INVALID_BUNDLE", "profile bundle must have version 1");
  }
  if (!isObject(bundle.profiles)) {
    throw bundleError("INVALID_BUNDLE", "profile bundle profiles must be an object");
  }
  const profiles = bundle.profiles;
  const visiting = new Set<string>();
  async function resolveProfile(name: string): Promise<DebateConfig> {
    if (!Object.hasOwn(profiles, name)) {
      throw bundleError("UNKNOWN_PROFILE", `unknown profile: ${name}`);
    }
    if (visiting.has(name)) {
      throw bundleError("INVALID_BUNDLE", `profile inheritance cycle at: ${name}`);
    }
    const profile = profiles[name];
    if (!isObject(profile)) {
      throw bundleError("INVALID_BUNDLE", `profile ${name} must be an object`);
    }
    const hasConfig = Object.hasOwn(profile, "config");
    const hasParent = Object.hasOwn(profile, "extends");
    const hasOverrides = Object.hasOwn(profile, "overrides");
    if (!hasConfig && !hasParent && !hasOverrides) {
      throw bundleError("INVALID_BUNDLE", `profile ${name} must have config, extends, or overrides`);
    }
    for (const key of ["config", "extends"] as const) {
      if (Object.hasOwn(profile, key) && (typeof profile[key] !== "string" || profile[key].trim() === "")) {
        throw bundleError("INVALID_BUNDLE", `profile ${name} ${key} must be a non-empty string`);
      }
    }
    visiting.add(name);
    const parent = hasParent ? await resolveProfile(profile.extends as string) : {};
    let result = parent;
    if (hasConfig) {
      const configPath = resolve(dirname(absoluteBundlePath), profile.config as string);
      const configText = await readFile(configPath, "utf8");
      result = hasParent || hasOverrides
        ? overlayConfig(parent, parseDebateConfigOverlay(configText))
        : parseDebateConfig(configText);
    }
    if (hasOverrides) {
      const overrides = parseOverrides(profile.overrides);
      result = overlayConfig(result, overrides.config);
      if (overrides.removeJudge) delete result.judge;
    }
    visiting.delete(name);
    return result;
  }

  const result = await resolveProfile(profileName);
  if (result.participants !== undefined && result.participants.length < 2) {
    throw new Error(`debate config: a debate needs at least 2 participants (got ${result.participants.length})`);
  }
  return result;
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { parseDebateConfig } from "../src/config.ts";
import { loadProfileBundle } from "../src/profile-bundle.ts";

const yaml = "rounds: 1\nrepo: ../repo\nparticipants:\n  - adapter: claude\n    model: sonnet\n  - adapter: codex\njudge:\n  adapter: claude\n  model: opus\n";

async function fixture(t: { after: (fn: () => Promise<void>) => void }) {
  const dir = await mkdtemp(join(tmpdir(), "disputatio-bundle-"));
  t.after(() => rm(dir, { recursive: true, force: true }));
  const bundlePath = join(dir, "bundle.json");
  const configPath = join(dir, "configs", "fast.yaml");
  await mkdir(join(dir, "configs"));
  await writeFile(configPath, yaml);
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: { fast: { config: "configs/fast.yaml" } } }));
  return { dir, bundlePath, configPath };
}

test("loads relative config paths from the bundle directory with independently owned results", async (t) => {
  const { bundlePath, configPath } = await fixture(t);
  const before = await Promise.all([readFile(bundlePath), readFile(configPath)]);
  const first = await loadProfileBundle(bundlePath, "fast");
  assert.deepEqual(first, parseDebateConfig(yaml));
  first.rounds = 99;
  first.participants![0].model = "changed";
  first.participants!.push({ adapter: "pi" });
  first.judge!.model = "changed";
  const second = await loadProfileBundle(relative(process.cwd(), bundlePath), "fast");
  assert.deepEqual(second, parseDebateConfig(yaml));
  assert.deepEqual(await Promise.all([readFile(bundlePath), readFile(configPath)]), before);
});

test("selects only the named profile, including names inherited by ordinary objects", async (t) => {
  const { bundlePath } = await fixture(t);
  await writeFile(bundlePath, '{"version":1,"profiles":{"__proto__":{"config":"configs/fast.yaml"},"unused":null}}');
  assert.deepEqual(await loadProfileBundle(bundlePath, "__proto__"), parseDebateConfig(yaml));
  for (const name of ["fast", "toString", "constructor"]) {
    await assert.rejects(loadProfileBundle(bundlePath, name), { code: "UNKNOWN_PROFILE" });
  }
});

test("rejects invalid JSON, bundle shapes, versions, and profiles maps", async (t) => {
  const { bundlePath } = await fixture(t);
  const invalid = [
    "{", "null", "[]", "1", '"bundle"',
    ...[
      {}, { version: 2, profiles: {} }, { version: "1", profiles: {} },
      { version: 1 }, { version: 1, profiles: null },
      { version: 1, profiles: [] }, { version: 1, profiles: "fast" },
      { version: 1, profiles: 1 }, { version: 1, profiles: true },
    ].map(value => JSON.stringify(value)),
  ];
  for (const text of invalid) {
    await writeFile(bundlePath, text);
    await assert.rejects(loadProfileBundle(bundlePath, "fast"), { code: "INVALID_BUNDLE" });
    assert.equal(await readFile(bundlePath, "utf8"), text);
  }
});

test("rejects malformed selected profiles", async (t) => {
  const { bundlePath } = await fixture(t);
  for (const profile of [null, [], "configs/fast.yaml", 1, true, {}, { config: null }, { config: [] }, { config: 1 }, { config: "" }, { config: "  " }]) {
    const text = JSON.stringify({ version: 1, profiles: { fast: profile } });
    await writeFile(bundlePath, text);
    await assert.rejects(loadProfileBundle(bundlePath, "fast"), { code: "INVALID_BUNDLE" });
    assert.equal(await readFile(bundlePath, "utf8"), text);
  }
});

test("preserves filesystem errors for missing config and bundle files", async (t) => {
  const { bundlePath, configPath, dir } = await fixture(t);
  await rm(configPath);
  await assert.rejects(loadProfileBundle(bundlePath, "fast"), { code: "ENOENT" });
  await assert.rejects(loadProfileBundle(join(dir, "missing.json"), "fast"), { code: "ENOENT" });
});

test("preserves YAML parser errors without modifying the inputs", async (t) => {
  const { bundlePath, configPath } = await fixture(t);
  const invalidYaml = "round: 2\n";
  await writeFile(configPath, invalidYaml);
  const before = await readFile(bundlePath);
  await assert.rejects(loadProfileBundle(bundlePath, "fast"), /debate config line 1: unknown key "round"/);
  assert.equal(await readFile(configPath, "utf8"), invalidYaml);
  assert.deepEqual(await readFile(bundlePath), before);
});

test("inherits through multiple parents, replacing scalars and whole judge and participant specs", async (t) => {
  const { bundlePath, configPath, dir } = await fixture(t);
  const base = "rounds: 3\nrepo: ../repo\ntimeoutMinutes: 10\nparticipants:\n  - adapter: claude\n    model: sonnet\n    effort: high\n  - adapter: codex\n    model: original\njudge:\n  adapter: claude\n  model: opus\n  effort: high\n";
  const childPath = join(dir, "configs", "child.yaml");
  const grandchildPath = join(dir, "grandchild.yaml");
  await writeFile(configPath, base);
  await writeFile(childPath, "rounds: 0\nparticipants:\n  - adapter: claude\n    model: updated\njudge:\n  adapter: codex\n");
  await writeFile(grandchildPath, "repo: ./child-repo\nparticipants:\n  - adapter: pi\n  - adapter: codex\n    effort: low\n  - adapter: agy\n");
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: {
    base: { config: "configs/fast.yaml" },
    child: { extends: "base", config: "configs/child.yaml" },
    grandchild: { extends: "child", config: "grandchild.yaml" },
    alias: { extends: "grandchild" },
  } }));
  const paths = [bundlePath, configPath, childPath, grandchildPath];
  const before = await Promise.all(paths.map(path => readFile(path)));
  const expected = {
    rounds: 0, repo: "./child-repo", timeoutMinutes: 10,
    participants: [
      { adapter: "claude", model: "updated" },
      { adapter: "codex", effort: "low" },
      { adapter: "pi" },
      { adapter: "agy" },
    ],
    judge: { adapter: "codex" },
  };
  const result = await loadProfileBundle(bundlePath, "alias");
  assert.deepEqual(result, expected);
  result.rounds = 99;
  result.participants![0].model = "mutated";
  result.participants![1].effort = "mutated";
  result.participants!.pop();
  result.judge!.model = "mutated";
  assert.deepEqual(await loadProfileBundle(bundlePath, "alias"), expected);
  assert.deepEqual(await loadProfileBundle(bundlePath, "base"), parseDebateConfig(base));
  assert.deepEqual(await Promise.all(paths.map(path => readFile(path))), before);
});

test("omitted child values inherit, and an extends-only profile owns its result", async (t) => {
  const { bundlePath, dir } = await fixture(t);
  await writeFile(join(dir, "scalar.yaml"), "timeoutMinutes: 2\n");
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: {
    base: { config: "configs/fast.yaml" },
    child: { extends: "base", config: "scalar.yaml" },
    alias: { extends: "child" },
  } }));
  const [first, second] = await Promise.all([
    loadProfileBundle(bundlePath, "alias"), loadProfileBundle(bundlePath, "alias"),
  ]);
  assert.deepEqual(first, { ...parseDebateConfig(yaml), timeoutMinutes: 2 });
  first.participants![0].model = "mutated";
  first.judge!.model = "mutated";
  assert.deepEqual(second, { ...parseDebateConfig(yaml), timeoutMinutes: 2 });
});

test("rejects malformed inheritance fields even when config or a parent is valid", async (t) => {
  const { bundlePath } = await fixture(t);
  const invalid = [null, [], {}, 1, true, "", "  "];
  for (const profile of [
    ...invalid.map(value => ({ config: "configs/fast.yaml", extends: value })),
    ...invalid.map(value => ({ config: value, extends: "base" })),
  ]) {
    await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: {
      base: { config: "configs/fast.yaml" }, child: profile,
    } }));
    await assert.rejects(loadProfileBundle(bundlePath, "child"), { code: "INVALID_BUNDLE" });
