test("judge null removes inherited and local judges and remains absent through inheritance", async (t) => {
  const { bundlePath } = await fixture(t);
  await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: {
    base: { config: "configs/fast.yaml" },
    inherited: { extends: "base", overrides: { judge: null } },
    local: { config: "configs/fast.yaml", overrides: { judge: null } },
    alias: { extends: "inherited", overrides: { rounds: 0 } },
    restored: { extends: "alias", overrides: { judge: { adapter: "pi" } } },
    absent: { overrides: { judge: null } },
  } }));
  const expected = parseDebateConfig(yaml);
  delete expected.judge;
  for (const name of ["inherited", "local"]) {
    const result = await loadProfileBundle(bundlePath, name);
    assert.deepEqual(result, expected);
    assert.equal(Object.hasOwn(result, "judge"), false);
  }
  assert.deepEqual(await loadProfileBundle(bundlePath, "alias"), { ...expected, rounds: 0 });
  assert.deepEqual(await loadProfileBundle(bundlePath, "restored"), { ...expected, rounds: 0, judge: { adapter: "pi" } });
  assert.deepEqual(await loadProfileBundle(bundlePath, "absent"), {});
  assert.deepEqual(await loadProfileBundle(bundlePath, "base"), parseDebateConfig(yaml));
});

