  if (typeof value.adapter !== "string") throw new Error("spec requires an adapter");
}

function parseOverrides(value: unknown): { config: DebateConfig; removeJudge: boolean } {
  try {
    if (!isObject(value)) throw new Error("overrides must be an object");
    for (const [key, setting] of Object.entries(value)) {
      switch (key) {
        case "rounds":
        case "timeoutMinutes":
          if (typeof setting !== "number" || !Number.isFinite(setting)) {
            throw new Error(`${key} must be a finite number`);
          }
          break;
        case "repo":
          if (typeof setting !== "string") throw new Error("repo must be a string");
          break;
        case "participants":
          if (!Array.isArray(setting)) throw new Error("participants must be an array");
          setting.forEach(validateOverrideSpec);
          break;
        case "judge":
          if (setting !== null) validateOverrideSpec(setting);
          break;
        default:
          throw new Error(`unknown override key: ${key}`);
      }
    }
    const config = { ...value };
    const removeJudge = config.judge === null;
    if (removeJudge) delete config.judge;
    const parsed = parseDebateConfigOverlay(serializeDebateConfig(config as DebateConfig));
    // The minimal YAML serializer cannot represent every JSON string. Refuse
    // lossy round trips (quotes, escapes, newlines) instead of changing settings.
    if (!isDeepStrictEqual(parsed, config)) throw new Error("override settings do not round-trip through config YAML");
    return { config: parsed, removeJudge };
  } catch (error) {
    throw bundleError("INVALID_BUNDLE", `invalid overrides: ${error instanceof Error ? error.message : String(error)}`);
  }
}

function overlayConfig(parent: DebateConfig, child: DebateConfig): DebateConfig {
  // Every supplied value replaces its parent value, including the entire
  // participant list in its supplied order. Absent keys inherit unchanged.
  return { ...parent, ...child };
}

// Read and parse afresh on every load: inputs stay untouched and callers own
// their entire configuration, including participant and judge objects.
export async function loadProfileBundle(bundlePath: string, profileName?: string): Promise<DebateConfig> {
  const absoluteBundlePath = await realpath(bundlePath);
  const text = await readFile(absoluteBundlePath, "utf8");
  let bundle: unknown;
  try {
    bundle = JSON.parse(text);
  } catch {
    throw bundleError("INVALID_BUNDLE", "profile bundle must contain valid JSON");
  }
  if (!isObject(bundle) || bundle.version !== 1) {
    throw bundleError("INVALID_BUNDLE", "profile bundle must have version 1");
  }
  if (!isObject(bundle.profiles)) {
    throw bundleError("INVALID_BUNDLE", "profile bundle profiles must be an object");
  }
  if (profileName === undefined) {
    if (!Object.hasOwn(bundle, "defaultProfile")) {
      throw bundleError("PROFILE_REQUIRED", "select a profile or set defaultProfile in the bundle");
    }
    if (typeof bundle.defaultProfile !== "string") {
      throw bundleError("INVALID_BUNDLE", "profile bundle defaultProfile must be a string");
    }
    profileName = bundle.defaultProfile;
  }
  const profiles = bundle.profiles;
  const visiting = new Set<string>();
  const chain: Record<string, unknown>[] = [];
  let name = profileName;
  // Walk iteratively so even a long inheritance chain or cycle cannot exhaust
  // the call stack. Apply the collected profiles in parent-first order below.
  while (true) {
    if (!Object.hasOwn(profiles, name)) {
      throw bundleError("UNKNOWN_PROFILE", `unknown profile: ${name}`);
    }
    if (visiting.has(name)) {
      throw bundleError("PROFILE_CYCLE", `profile inheritance cycle at: ${name}`);
    }
    const profile = profiles[name];
    if (!isObject(profile)) {
      throw bundleError("INVALID_BUNDLE", `profile ${name} must be an object`);
    }
    const hasConfig = Object.hasOwn(profile, "config");
    const hasParent = Object.hasOwn(profile, "extends");
    const hasOverrides = Object.hasOwn(profile, "overrides");
    if (!hasConfig && !hasParent && !hasOverrides) {
      throw bundleError("INVALID_BUNDLE", `profile ${name} must have config, extends, or overrides`);
    }
    for (const key of ["config", "extends"] as const) {
      if (Object.hasOwn(profile, key) && (typeof profile[key] !== "string" || profile[key].trim() === "")) {
        throw bundleError("INVALID_BUNDLE", `profile ${name} ${key} must be a non-empty string`);
      }
    }
    visiting.add(name);
    chain.push(profile);
    if (!hasParent) break;
    name = profile.extends as string;
  }

  let result: DebateConfig = {};
  for (const profile of chain.reverse()) {
    const hasConfig = Object.hasOwn(profile, "config");
    const hasParent = Object.hasOwn(profile, "extends");
    const hasOverrides = Object.hasOwn(profile, "overrides");
    if (hasConfig) {
      const configPath = await resolveConfigPath(dirname(absoluteBundlePath), profile.config as string);
      const configText = await readFile(configPath, "utf8");
      result = hasParent || hasOverrides
        ? overlayConfig(result, parseDebateConfigOverlay(configText))
        : parseDebateConfig(configText);
    }
    if (hasOverrides) {
      const overrides = parseOverrides(profile.overrides);
      result = overlayConfig(result, overrides.config);
      if (overrides.removeJudge) delete result.judge;
    }
  }

  if (result.participants !== undefined && result.participants.length < 2) {
    throw new Error(`debate config: a debate needs at least 2 participants (got ${result.participants.length})`);
  }
  return result;
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtemp, mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { parseDebateConfig, serializeDebateConfig } from "../src/config.ts";

const cli = fileURLToPath(new URL("../src/profile-cli.ts", import.meta.url));

async function fixture(t: { after: (fn: () => Promise<void>) => void }) {
  const dir = await mkdtemp(join(tmpdir(), "disputatio-profile-cli-"));
  const bundlePath = join(dir, "bundle.json");
  const configPath = join(dir, "base.yaml");
  const marker = join(dir, "participant-ran");
  t.after(async () => {
    try {
      await assert.rejects(readFile(marker), { code: "ENOENT" });
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });
  const binDir = join(dir, "bin");
  await mkdir(binDir);
  // PATH contains only local tripwires: any accidental participant invocation
  // leaves evidence, and no installed agent CLI can run from these tests.
  for (const name of ["claude", "codex", "agy", "pi", "copilot"]) {
    await writeFile(join(binDir, name), '#!/bin/sh\nprintf invoked > "$PARTICIPANT_MARKER"\nexit 99\n', { mode: 0o755 });
  }
  const yaml = "# source formatting is not canonical\nrepo: ./repo\nrounds: 2\nparticipants:\n  - adapter: claude\n    model: sonnet\n  - adapter: codex\njudge:\n  adapter: pi\n";
  await writeFile(configPath, yaml);
  await writeFile(bundlePath, JSON.stringify({ version: 1, defaultProfile: "child", profiles: {
    base: { config: "base.yaml" },
    child: { extends: "base", overrides: {
      rounds: 0, participants: [{ adapter: "codex", model: "updated" }, { adapter: "pi" }], judge: null,
    } },
  } }));
  const run = (args: string[]) => {
    const result = spawnSync(process.execPath, [cli, ...args], {
      cwd: dir, encoding: "utf8", timeout: 5000,
      env: { ...process.env, PATH: binDir, PARTICIPANT_MARKER: marker },
    });
    assert.ifError(result.error);
    assert.equal(result.signal, null);
    return result;
  };
  return { dir, bundlePath, configPath, yaml, run };
}

test("CLI renders default and explicit profiles as canonical reusable YAML without writes or participants", async (t) => {
  const { dir, bundlePath, configPath, yaml, run } = await fixture(t);
  const before = await Promise.all([readFile(bundlePath), readFile(configPath)]);
  const files = await readdir(dir, { recursive: true });
  const expected = {
    rounds: 0, repo: "./repo", participants: [{ adapter: "codex", model: "updated" }, { adapter: "pi" }],
  };
  const rendered = run(["--bundle", "bundle.json"]);
  assert.equal(rendered.status, 0);
  assert.equal(rendered.stderr, "");
  assert.deepEqual(parseDebateConfig(rendered.stdout), expected);
  assert.equal(rendered.stdout, "rounds: 0\nrepo: ./repo\nparticipants:\n  - adapter: codex\n    model: updated\n  - adapter: pi\n");
  const explicit = run(["--profile", "base", "--bundle", bundlePath]);
  assert.equal(explicit.status, 0);
  assert.equal(explicit.stderr, "");
  assert.equal(explicit.stdout, serializeDebateConfig(parseDebateConfig(yaml)));
  assert.deepEqual(await Promise.all([readFile(bundlePath), readFile(configPath)]), before);
  assert.deepEqual(await readdir(dir, { recursive: true }), files);
});

test("CLI rejects missing arguments, unknown flags, and extra arguments with empty stdout", async (t) => {
  const { bundlePath, run } = await fixture(t);
  for (const args of [[], ["--profile", "base"], ["--bundle"], ["--bundle", ""],
    ["--bundle", "--profile", "base"], ["--bundle", bundlePath, "--profile"],
    ["--bundle", bundlePath, "--profile", ""], ["--bundle", bundlePath, "--unknown"],
    ["--bundle", bundlePath, "extra"], ["--bundle", bundlePath, "--bundle", bundlePath],
    ["--bundle", bundlePath, "--profile", "base", "--profile", "child"],
  ]) {
    const result = run(args);
    assert.equal(result.status, 1, JSON.stringify(args));
    assert.equal(result.stdout, "");
    assert.match(result.stderr, /required|requires|unknown|duplicate/);
    assert.match(result.stderr, /usage:/);
  }
});

test("CLI reports loader error codes on stderr and never emits partial YAML", async (t) => {
  const { bundlePath, run } = await fixture(t);
  const cases: [string, string[], string][] = [
    ["{", [], "INVALID_BUNDLE"],
    [JSON.stringify({ version: 1, profiles: {} }), [], "PROFILE_REQUIRED"],
    [JSON.stringify({ version: 1, defaultProfile: "missing", profiles: {} }), [], "UNKNOWN_PROFILE"],
    [JSON.stringify({ version: 1, profiles: {} }), ["--profile", "missing"], "UNKNOWN_PROFILE"],
    [JSON.stringify({ version: 1, defaultProfile: "child", profiles: { child: { extends: "missing" } } }), [], "UNKNOWN_PROFILE"],
    [JSON.stringify({ version: 1, defaultProfile: "loop", profiles: { loop: { extends: "loop" } } }), [], "PROFILE_CYCLE"],
    [JSON.stringify({ version: 1, defaultProfile: "bad", profiles: { bad: { config: "../outside.yaml" } } }), [], "UNSAFE_CONFIG_PATH"],
    [JSON.stringify({ version: 1, defaultProfile: "bad", profiles: { bad: { config: "missing.yaml" } } }), [], "ENOENT"],
  ];
  for (const [text, args, code] of cases) {
    await writeFile(bundlePath, text);
    const result = run(["--bundle", bundlePath, ...args]);
    assert.equal(result.status, 1);
    assert.equal(result.stdout, "");
    assert.ok(result.stderr.includes(code), result.stderr);
    assert.equal(await readFile(bundlePath, "utf8"), text);
  }
  const missing = run(["--bundle", "missing.json"]);
  assert.equal(missing.status, 1);
  assert.equal(missing.stdout, "");
  assert.match(missing.stderr, /ENOENT/);
});

test("CLI reports YAML and serialization failures without stdout or input changes", async (t) => {
  const { bundlePath, configPath, run } = await fixture(t);
  const bundleBefore = await readFile(bundlePath);
  for (const [text, diagnostic] of [
    ["round: 2\n", /unknown key "round"/],
    ["rounds: 2\nrepo: '#unrepresentable'\n", /comment marker/],
  ] as const) {
    await writeFile(configPath, text);
    const result = run(["--bundle", bundlePath, "--profile", "base"]);
    assert.equal(result.status, 1);
    assert.equal(result.stdout, "");
    assert.match(result.stderr, diagnostic);
    assert.equal(await readFile(configPath, "utf8"), text);
    assert.deepEqual(await readFile(bundlePath), bundleBefore);
  }
});
"}

